<?= $this->include('partials/header') ?><main class="dc-content"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="dc-page-title">Carrinhos</h1><p class="dc-page-subtitle">Seu catálogo pessoal de modelos.</p></div><a class="btn btn-primary" href="/carrinhos/novo">+ Novo carrinho</a></div><?php if(session('message')): ?><div class="alert alert-success"><?= esc(session('message')) ?></div><?php endif ?><form class="mb-3"><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Pesquisar por modelo ou marca..."></form><div class="row g-3"><?php foreach($products as $p): ?><div class="col-sm-6 col-lg-3"><article class="card h-100 overflow-hidden"><?php if($p['image_id']): ?><img src="/imagens/carrinhos/<?= $p['image_id'] ?>" class="card-img-top" style="height:150px;object-fit:cover" alt="<?= esc($p['name']) ?>"><?php endif ?><div class="card-body"><span class="badge text-bg-light"><?= esc($p['brand']) ?></span><h2 class="h6 mt-2"><?= esc($p['name']) ?></h2><small class="text-secondary d-block mb-2"><?= esc($p['scale'] ?? '') ?> <?= esc($p['series'] ?? '') ?></small><a class="btn btn-sm btn-outline-primary" href="/carrinhos/<?= $p['id'] ?>/editar">Editar</a><form method="post" action="/carrinhos/<?= $p['id'] ?>/excluir" class="d-inline"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir este carrinho?')">Excluir</button></form></div></article></div><?php endforeach ?></div><div class="dc-pagination mt-4"><?= $pager->links('default', 'diecast') ?></div></main><?= $this->include('partials/footer') ?>
